def compute(vars):
    net_income = vars["Net Income"]
    total_assets = vars["Total Assets"]

    if total_assets == 0:
        value = None
    else:
        value = net_income / total_assets

    return {
        "value": value,
        "trace": {
            "Net Income": net_income,
            "Total Assets": total_assets,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio",
            },
        },
    }
